file.content:
/* Template Form Styles - Based on Figma Design */

.template-form-modal .modal-content {
  border-radius: 12px;
  box-shadow: 0px 4px 8px 1px rgba(0, 0, 0, 0.25);
  border: none;
}

.template-modal-header {
  padding: 24px 24px 0 24px;
  border-bottom: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.template-modal-title {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 24px;
  line-height: 32px;
  color: #1C1C1D;
  margin: 0;
}

.template-close-btn {
  background: transparent;
  border: none;
  width: 44px;
  height: 44px;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color 0.2s;
}

.template-close-btn:hover {
  background-color: #F2F2F7;
}

.template-close-btn i {
  font-size: 20px;
  color: #1C1C1D;
}

.template-modal-body {
  padding: 24px;
}

.template-label {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 12px;
  line-height: 16px;
  color: #4D4D4F;
  margin-bottom: 8px;
  letter-spacing: 0.06px;
}

.template-input,
.template-textarea {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
  color: #4D4D4F;
  border: 1px solid #909093;
  border-radius: 8px;
  padding: 10px 12px;
  letter-spacing: 0.08px;
}

.template-input:focus,
.template-textarea:focus {
  border-color: #FEBF1D;
  box-shadow: 0 0 0 0.2rem rgba(254, 191, 29, 0.25);
}

.template-input::placeholder,
.template-textarea::placeholder {
  color: #909093;
}

.template-editor-container {
  position: relative;
  border: 1px solid #909093;
  border-radius: 8px;
  background: white;
}

.template-textarea {
  border: none;
  border-radius: 8px 8px 0 0;
  resize: none;
  padding: 12px;
}

.template-textarea:focus {
  box-shadow: none;
  border: none;
}

.template-char-count {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 12px;
  line-height: 16px;
  color: #1C1C1D;
  text-align: right;
  padding: 0 12px 12px;
  letter-spacing: 0.06px;
}

.template-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border-top: 1px solid #909093;
  background: white;
  border-radius: 0 0 8px 8px;
}

.toolbar-group {
  display: flex;
  gap: 2px;
}

.toolbar-btn {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.2s;
  color: #1C1C1D;
  font-size: 14px;
}

.toolbar-btn:hover {
  background-color: #F2F2F7;
}

.toolbar-btn-text {
  width: auto;
  padding: 0 8px;
  font-family: 'Noto Sans', sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.4;
  white-space: nowrap;
}

.toolbar-divider {
  width: 1px;
  height: 28px;
  background-color: #909093;
}

.template-variables-section {
  margin-top: 20px;
  padding: 16px;
  background-color: #F2F2F7;
  border-radius: 8px;
}

.template-section-title {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
  color: #1C1C1D;
  margin-bottom: 16px;
  letter-spacing: 0.08px;
}

.template-input-sm {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 20px;
  color: #4D4D4F;
  border: 1px solid #909093;
  border-radius: 8px;
  padding: 8px 12px;
}

.template-var-btn-insert {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 12px;
  color: #FEBF1D;
  text-decoration: none;
  padding: 0;
}

.template-var-btn-insert:hover {
  color: #e0a819;
}

.template-var-btn-remove {
  color: #F73B3B;
  padding: 0;
  margin-left: 8px;
}

.template-var-btn-remove:hover {
  color: #d63030;
}

.template-modal-footer {
  padding: 24px;
  border-top: none;
  display: flex;
  gap: 20px;
}

.template-btn-secondary {
  flex: 1;
  height: 44px;
  border: 1px solid #1C1C1D;
  border-radius: 8px;
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
  color: #1C1C1D;
  background: white;
  letter-spacing: 0.07px;
}

.template-btn-secondary:hover {
  background-color: #F2F2F7;
  border-color: #1C1C1D;
  color: #1C1C1D;
}

.template-btn-primary {
  flex: 1;
  height: 44px;
  background-color: #FEBF1D;
  border: none;
  border-radius: 8px;
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
  color: #1C1C1D;
  letter-spacing: 0.07px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.template-btn-primary:hover {
  background-color: #e0a819;
  color: #1C1C1D;
}

.template-btn-primary:focus {
  background-color: #FEBF1D;
  box-shadow: 0 0 0 0.2rem rgba(254, 191, 29, 0.5);
}

