/* Template Form Styles - Based on Figma Design */

.template-form-modal .modal-content {
  border-radius: 12px;
  box-shadow: 0px 4px 8px 1px rgba(0, 0, 0, 0.25);
  border: none;
}

.template-modal-header {
  padding: 24px 24px 0 24px;
  border-bottom: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.template-modal-title {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 24px;
  line-height: 32px;
  color: #1C1C1D;
  margin: 0;
}

.template-close-btn {
  background: transparent;
  border: none;
  width: 44px;
  height: 44px;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color 0.2s;
}

.template-close-btn:hover {
  background-color: #F2F2F7;
}

.template-close-btn i {
  font-size: 20px;
  color: #1C1C1D;
}

.template-modal-body {
  padding: 24px;
}

.template-label {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 12px;
  line-height: 16px;
  color: #4D4D4F;
  margin-bottom: 8px;
  letter-spacing: 0.06px;
}

.template-input,
.template-textarea {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
