.template-input-sm {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 20px;
  color: #4D4D4F;
  border: 1px solid #909093;
  border-radius: 8px;
  padding: 8px 12px;
