  margin-left: 8px;
}

.template-var-btn-remove:hover {
  color: #d63030;
}

.template-modal-footer {
  padding: 24px;
  border-top: none;
  display: flex;
  gap: 20px;
}

.template-btn-secondary {
  flex: 1;
  height: 44px;
  border: 1px solid #1C1C1D;
  border-radius: 8px;
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
  color: #1C1C1D;
  background: white;
  letter-spacing: 0.07px;
}

.template-btn-secondary:hover {
  background-color: #F2F2F7;
  border-color: #1C1C1D;
  color: #1C1C1D;
}

.template-btn-primary {
  flex: 1;
  height: 44px;
  background-color: #FEBF1D;
  border: none;
  border-radius: 8px;
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
  color: #1C1C1D;
  letter-spacing: 0.07px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.template-btn-primary:hover {
  background-color: #e0a819;
  color: #1C1C1D;
}

.template-btn-primary:focus {
  background-color: #FEBF1D;
  box-shadow: 0 0 0 0.2rem rgba(254, 191, 29, 0.5);
}

