.template-preview-content .wa-strikethrough {
  text-decoration: line-through;
}

.template-preview-content .wa-code {
  font-family: 'SF Mono', 'Monaco', 'Inconsolata', 'Roboto Mono', monospace;
  background-color: #F2F2F7;
