  display: flex;
  gap: 20px;
}

.template-btn-secondary {
  flex: 1;
  height: 44px;
  border: 1px solid #1C1C1D;
  border-radius: 8px;
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
